<?php /* VIVA NOTE: One room detail screen including price, slots and occupancy state. */ ?><div class="toolbar"><p>Belongs to <?=e($room['property_title'])?></p><a href="<?=e(url('/rooms'))?>">← Rooms</a></div><div class="detail-grid"><section class="panel"><h3>Room details</h3><dl class="details"><dt>Type</dt><dd><?=e(pill($room['room_type']))?></dd><dt>Capacity</dt><dd><?=e($room['slot_capacity'])?></dd><dt>Monthly rent</dt><dd><?=e(cash($room['price']))?></dd><dt>Deposit</dt><dd><?=e(cash($room['deposit_amount']))?></dd><dt>Furnishing</dt><dd><?=e(pill($room['furnishing']))?></dd><dt>Gender preference</dt><dd><?=e(pill($room['gender_preference']))?></dd><dt>House rules</dt><dd><?=e($room['house_rules']?:'—')?></dd><dt>Rent lock until</dt><dd><?=e(date_label($room['rent_locked_until']))?></dd></dl><div class="form-actions"><a class="btn" href="<?=e(url('/room/edit',['id'=>$room['room_id']]))?>">Edit room</a><a class="btn secondary" href="<?=e(url('/room/photos',['id'=>$room['room_id']]))?>">Photos</a></div></section>
<section class="panel"><h3>Editing restrictions</h3><div class="status-line"><strong>Room details:</strong><span class="status"><?= !empty($windows['details_open'])?'Editable':'Locked'?></span></div><div class="status-line"><strong>Monthly rent:</strong><span class="status"><?= !empty($windows['rent_open'])?'Editable':'Annual lock'?></span></div><p class="hint">These time limits protect published room information.</p></section></div>
<section class="panel"><div class="panel-title"><h3>Physical room slots</h3><span class="availability-badge <?=e($availability[1])?>"><?=e($availability[0])?></span></div><p class="hint">Available: <?=e($availability_counts['available_slots'])?> · Reserved: <?=e($availability_counts['reserved_slots'])?> · Occupied: <?=e($availability_counts['occupied_slots'])?> · Blocked: <?=e($availability_counts['blocked_slots'])?>. Fully reserved or occupied rooms cannot receive new requests.</p><div class="slot-grid"><?php foreach($slots as $slot):?><div class="slot <?=$slot['status_display']==='occupied'?'busy':($slot['status_display']==='reserved'?'reserved':'')?>"><strong>Slot <?=e($slot['slot_number'])?></strong><small><?=e(pill($slot['status_display']))?></small></div><?php endforeach;?></div></section>
